"use strict";(globalThis.webpackChunkdocs=globalThis.webpackChunkdocs||[]).push([[1823],{39280(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"Introduction","collapsible":false,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/getting-started","label":"Getting started","docId":"introduction/getting-started","unlisted":false},{"type":"link","href":"/enriched-markdown/introduction/core-concepts","label":"Core concepts","docId":"introduction/core-concepts","unlisted":false},{"type":"link","href":"/enriched-markdown/introduction/supported-features","label":"Feature support","docId":"introduction/supported-features","unlisted":false}],"href":"/enriched-markdown/category/introduction"},{"type":"category","label":"iOS","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Basics","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/ios/basics/installation","label":"Installation","docId":"ios/basics/installation","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/basics/your-first-screen","label":"Your first markdown screen","docId":"ios/basics/your-first-screen","unlisted":false}]},{"type":"category","label":"API reference","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/ios/api-reference/enriched-markdown-text","label":"EnrichedMarkdownText","docId":"ios/api-reference/enriched-markdown-text","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/api-reference/markdown-theme","label":"MarkdownTheme","docId":"ios/api-reference/markdown-theme","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/api-reference/style-properties","label":"Style properties","docId":"ios/api-reference/style-properties","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/api-reference/element-structure","label":"Element structure","docId":"ios/api-reference/element-structure","unlisted":false}]},{"type":"category","label":"Guides","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/ios/guides/parser-extensions","label":"Parser extensions","docId":"ios/guides/parser-extensions","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/guides/latex-math","label":"LaTeX math","docId":"ios/guides/latex-math","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/guides/syntax-highlighting","label":"Syntax highlighting","docId":"ios/guides/syntax-highlighting","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/guides/image-caching","label":"Images and caching","docId":"ios/guides/image-caching","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/guides/custom-fonts","label":"Custom fonts","docId":"ios/guides/custom-fonts","unlisted":false},{"type":"link","href":"/enriched-markdown/ios/guides/uikit-interop","label":"UIKit interop","docId":"ios/guides/uikit-interop","unlisted":false}]}]},{"type":"category","label":"Android","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Basics","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/android/basics/installation","label":"Installation","docId":"android/basics/installation","unlisted":false},{"type":"link","href":"/enriched-markdown/android/basics/your-first-screen","label":"Your first markdown screen","docId":"android/basics/your-first-screen","unlisted":false}]},{"type":"category","label":"API reference","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/android/api-reference/enriched-markdown-text","label":"EnrichedMarkdownText","docId":"android/api-reference/enriched-markdown-text","unlisted":false},{"type":"link","href":"/enriched-markdown/android/api-reference/markdown-theme","label":"MarkdownTheme","docId":"android/api-reference/markdown-theme","unlisted":false},{"type":"link","href":"/enriched-markdown/android/api-reference/style-properties","label":"Style properties","docId":"android/api-reference/style-properties","unlisted":false},{"type":"link","href":"/enriched-markdown/android/api-reference/element-structure","label":"Element structure","docId":"android/api-reference/element-structure","unlisted":false}]},{"type":"category","label":"Guides","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/android/guides/parser-extensions","label":"Parser extensions","docId":"android/guides/parser-extensions","unlisted":false},{"type":"link","href":"/enriched-markdown/android/guides/latex-math","label":"LaTeX math","docId":"android/guides/latex-math","unlisted":false},{"type":"link","href":"/enriched-markdown/android/guides/code-highlighting","label":"Code highlighting","docId":"android/guides/code-highlighting","unlisted":false},{"type":"link","href":"/enriched-markdown/android/guides/image-caching","label":"Images and caching","docId":"android/guides/image-caching","unlisted":false},{"type":"link","href":"/enriched-markdown/android/guides/custom-fonts","label":"Custom fonts","docId":"android/guides/custom-fonts","unlisted":false},{"type":"link","href":"/enriched-markdown/android/guides/compose-interop","label":"Compose interop","docId":"android/guides/compose-interop","unlisted":false}]}]},{"type":"category","label":"React Native","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Basics","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/react-native/basics/installation","label":"Installation","docId":"react-native/basics/installation","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/basics/your-first-project","label":"Your first markdown view and editor","docId":"react-native/basics/your-first-project","unlisted":false}]},{"type":"category","label":"API reference","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/react-native/api-reference/enriched-markdown-text","label":"EnrichedMarkdownText","docId":"react-native/api-reference/enriched-markdown-text","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/api-reference/enriched-markdown-text-input","label":"EnrichedMarkdownTextInput","docId":"react-native/api-reference/enriched-markdown-text-input","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/api-reference/style-properties","label":"Style properties","docId":"react-native/api-reference/style-properties","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/api-reference/element-structure","label":"Element structure","docId":"react-native/api-reference/element-structure","unlisted":false}]},{"type":"category","label":"Guides","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/react-native/guides/markdown-flavors","label":"Markdown flavors","docId":"react-native/guides/markdown-flavors","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/link-pills","label":"Link pills","docId":"react-native/guides/link-pills","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/link-menus","label":"Link menus","docId":"react-native/guides/link-menus","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/web-support","label":"Web support","docId":"react-native/guides/web-support","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/web-editor","label":"Web editor","className":"sidebar-experimental","docId":"react-native/guides/web-editor","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/image-caching","label":"Image caching","docId":"react-native/guides/image-caching","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/native-assets","label":"Native assets","docId":"react-native/guides/native-assets","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/testing","label":"Testing","docId":"react-native/guides/testing","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/macos","label":"macOS support","docId":"react-native/guides/macos","unlisted":false},{"type":"link","href":"/enriched-markdown/react-native/guides/custom-block-renderers","label":"Custom block renderers","docId":"react-native/guides/custom-block-renderers","unlisted":false}]}]},{"type":"category","label":"Rich text formatting","collapsible":false,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/rich-text-formatting/mentions","label":"Mentions","docId":"rich-text-formatting/mentions","unlisted":false},{"type":"link","href":"/enriched-markdown/rich-text-formatting/latex-math","label":"LaTeX math","docId":"rich-text-formatting/latex-math","unlisted":false},{"type":"link","href":"/enriched-markdown/rich-text-formatting/code-highlighting","label":"Code-block highlighting","docId":"rich-text-formatting/code-highlighting","unlisted":false},{"type":"link","href":"/enriched-markdown/rich-text-formatting/markdown-streaming","label":"Markdown streaming","docId":"rich-text-formatting/markdown-streaming","unlisted":false},{"type":"link","href":"/enriched-markdown/rich-text-formatting/editor-style-text","label":"Editor-style text","docId":"rich-text-formatting/editor-style-text","unlisted":false}],"href":"/enriched-markdown/category/rich-text-formatting"},{"type":"category","label":"User experience","collapsible":false,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/user-experience/accessibility","label":"Accessibility","docId":"user-experience/accessibility","unlisted":false},{"type":"link","href":"/enriched-markdown/user-experience/rtl","label":"RTL support","docId":"user-experience/rtl","unlisted":false},{"type":"link","href":"/enriched-markdown/user-experience/copy-options","label":"Copy options","docId":"user-experience/copy-options","unlisted":false}],"href":"/enriched-markdown/category/user-experience"},{"type":"category","label":"Misc","collapsible":false,"collapsed":false,"items":[{"type":"link","href":"/enriched-markdown/misc/compatibility","label":"Compatibility","docId":"misc/compatibility","unlisted":false},{"type":"link","href":"/enriched-markdown/misc/breaking-changes","label":"Breaking changes","docId":"misc/breaking-changes","unlisted":false},{"type":"link","href":"/enriched-markdown/misc/known-limitations","label":"Known limitations","docId":"misc/known-limitations","unlisted":false},{"type":"link","href":"/enriched-markdown/misc/roadmap","label":"Roadmap","docId":"misc/roadmap","unlisted":false},{"type":"link","href":"/enriched-markdown/misc/contributing","label":"Contributing","docId":"misc/contributing","unlisted":false}],"href":"/enriched-markdown/category/misc"}]},"docs":{"android/api-reference/element-structure":{"id":"android/api-reference/element-structure","title":"Element structure","description":"This page is about what the renderer does with your Markdown: which constructs it understands, how they nest, and where the result differs from what the source looks like. For the properties that control their appearance, see Style properties.","sidebar":"tutorialSidebar"},"android/api-reference/enriched-markdown-text":{"id":"android/api-reference/enriched-markdown-text","title":"EnrichedMarkdownText","description":"EnrichedMarkdownText renders Markdown as fully native text. It parses with md4c and paints the result with Android\'s own text stack, so selection, TalkBack, and font scaling all behave like first-class native text.","sidebar":"tutorialSidebar"},"android/api-reference/markdown-theme":{"id":"android/api-reference/markdown-theme","title":"MarkdownTheme","description":"This page covers the composables that provide and build styles. For the styleable elements and their properties, see Style properties.","sidebar":"tutorialSidebar"},"android/api-reference/style-properties":{"id":"android/api-reference/style-properties","title":"Style properties reference","description":"Every Markdown element is styled through the markdownStyle { } DSL. This page lists each block you can open and the properties it takes. For how a style reaches a component and how layering works, see MarkdownTheme.","sidebar":"tutorialSidebar"},"android/basics/installation":{"id":"android/basics/installation","title":"Installation","description":"enriched-markdown-android is a standalone Android library - a Jetpack Compose component that renders Markdown as native text. It is published directly to Maven Central, so you add it to an Android app the way you add any other Gradle dependency.","sidebar":"tutorialSidebar"},"android/basics/your-first-screen":{"id":"android/basics/your-first-screen","title":"Your first markdown screen","description":"With the library installed, let\'s get Markdown onto the screen. By the end of this page you\'ll have rendered your first document and restyled it.","sidebar":"tutorialSidebar"},"android/guides/code-highlighting":{"id":"android/guides/code-highlighting","title":"Code highlighting","description":"Code coloring is built on tree-sitter and 14 bundled grammars. It ships as a separate artifact, code-highlight, rather than as part of compose, so an app that never shows code does not carry a parser it will not use.","sidebar":"tutorialSidebar"},"android/guides/compose-interop":{"id":"android/guides/compose-interop","title":"Compose interop","description":"EnrichedMarkdownText is a composable, but it is not made of composables. Underneath it is a native Android view hosted through AndroidView: a container that stacks one child view per segment of the document. Runs of ordinary blocks - paragraphs, headings, lists, quotes, code blocks - render into a TextView segment, while each top-level table, each top-level code block set to scroll, and each block a plugin draws (such as display math) gets a view of its own between them. Markdown rendering leans on Android\'s span and text-layout machinery, which is also what buys you real text selection, TalkBack, and system font scaling for free.","sidebar":"tutorialSidebar"},"android/guides/custom-fonts":{"id":"android/guides/custom-fonts","title":"Custom fonts","description":"Every style block that renders text takes a fontFamily, so you can set the typeface globally, per element, or both. This guide covers what you can pass, how it is resolved, and the limits worth knowing before you design around it.","sidebar":"tutorialSidebar"},"android/guides/image-caching":{"id":"android/guides/image-caching","title":"Images and caching","description":"Images in Markdown are loaded, decoded, and cached automatically - there is no image library to configure and no loader to inject. This guide covers where an image can come from and what happens to it on the way to the screen.","sidebar":"tutorialSidebar"},"android/guides/latex-math":{"id":"android/guides/latex-math","title":"LaTeX math","description":"Math rendering ships as a separate artifact, math, so an app that never shows a formula does not carry a typesetting engine it will not use. The artifact brings in RaTeX, a native LaTeX engine with the KaTeX fonts, which is why it is opt-in rather than part of compose.","sidebar":"tutorialSidebar"},"android/guides/parser-extensions":{"id":"android/guides/parser-extensions","title":"Parser extensions","description":"Markdown is not one language. Beyond the CommonMark core that every renderer agrees on, each flavor adds its own syntax, and this library lets you pick which of those additions are in play - per component, through the options parameter.","sidebar":"tutorialSidebar"},"introduction/core-concepts":{"id":"introduction/core-concepts","title":"Core concepts","description":"In Enriched Markdown, Markdown is the shared format between the two components. EnrichedMarkdownTextInput produces Markdown as the user types, and EnrichedMarkdownText consumes Markdown to render it. If you understand the Markdown syntax below, you understand what both components can express.","sidebar":"tutorialSidebar"},"introduction/getting-started":{"id":"introduction/getting-started","title":"Getting started","description":"Welcome to Enriched Markdown, a rich text solution built by Software Mansion.","sidebar":"tutorialSidebar"},"introduction/supported-features":{"id":"introduction/supported-features","title":"Feature support","description":"This page lists which features the library implements, organized by component","sidebar":"tutorialSidebar"},"ios/api-reference/element-structure":{"id":"ios/api-reference/element-structure","title":"Element structure","description":"This page is about what the renderer does with your Markdown: which constructs it understands, how they nest, and where the result differs from what the source looks like. For the properties that control their appearance, see Style properties.","sidebar":"tutorialSidebar"},"ios/api-reference/enriched-markdown-text":{"id":"ios/api-reference/enriched-markdown-text","title":"EnrichedMarkdownText","description":"EnrichedMarkdownText renders Markdown as fully native text. It parses with md4c and paints the result through TextKit, so selection, VoiceOver, and Dynamic Type all behave like first-class native text.","sidebar":"tutorialSidebar"},"ios/api-reference/markdown-theme":{"id":"ios/api-reference/markdown-theme","title":"MarkdownTheme","description":"This page covers the types that build and provide themes. For the styleable elements and their modifiers, see Style properties.","sidebar":"tutorialSidebar"},"ios/api-reference/style-properties":{"id":"ios/api-reference/style-properties","title":"Style properties reference","description":"Every Markdown element is styled by naming it in a MarkdownTheme { } builder and chaining modifiers onto it. This page lists each element and the modifiers it takes. For how a theme reaches a view and how layering works, see MarkdownTheme.","sidebar":"tutorialSidebar"},"ios/basics/installation":{"id":"ios/basics/installation","title":"Installation","description":"enriched-markdown-ios is a standalone Swift package - a SwiftUI view that renders Markdown as native text. You add it the way you add any other Swift package. The Markdown parser is C and C++ compiled from source into the package; the one prebuilt binary it references is the math engine behind the optional LaTeX product (see The products).","sidebar":"tutorialSidebar"},"ios/basics/your-first-screen":{"id":"ios/basics/your-first-screen","title":"Your first markdown screen","description":"With the package installed, let\'s get Markdown onto the screen. By the end of this page you\'ll have rendered your first document and restyled it.","sidebar":"tutorialSidebar"},"ios/guides/custom-fonts":{"id":"ios/guides/custom-fonts","title":"Custom fonts","description":"Pointing an element at your own typeface is one modifier:","sidebar":"tutorialSidebar"},"ios/guides/image-caching":{"id":"ios/guides/image-caching","title":"Images and caching","description":"Two things about images are easy to get wrong because nothing on screen tells you about them: far more sources work than alt suggests, and the caches that make re-rendering cheap are invisible and process-wide. This page covers both.","sidebar":"tutorialSidebar"},"ios/guides/latex-math":{"id":"ios/guides/latex-math","title":"LaTeX math","description":"Math rendering ships as a separate product, EnrichedMarkdownLaTeX, so an app that never shows a formula does not link a typesetting engine it will not use. The engine is a prebuilt binary dependency plus the KaTeX font files - a few megabytes of app size - which is why it is opt-in rather than part of the base package.","sidebar":"tutorialSidebar"},"ios/guides/parser-extensions":{"id":"ios/guides/parser-extensions","title":"Parser extensions","description":"MarkdownParsingOptions decides what the parser recognizes, not how it looks. An option that is off does not hide an element - it means the syntax was never an element in the first place. For the options that add new syntax, the markers then stay in the text as you typed them, so getting one wrong shows up as literal == or ^ in your output, not as an unstyled span. The two options that change an existing meaning fall back to the standard meaning instead.","sidebar":"tutorialSidebar"},"ios/guides/syntax-highlighting":{"id":"ios/guides/syntax-highlighting","title":"Syntax highlighting","description":"Code-block coloring ships as a separate product, EnrichedMarkdownSyntaxHighlighting, because it compiles the tree-sitter parsing library and a fixed set of language grammars into your app - about 8 MB of app size. An app that never shows code should not pay for that, so the base package draws every code block in a single color.","sidebar":"tutorialSidebar"},"ios/guides/uikit-interop":{"id":"ios/guides/uikit-interop","title":"UIKit interop","description":"The package\'s public surface is SwiftUI: EnrichedMarkdownText is a View, and everything else configures it through the environment. The UIKit text view underneath is an implementation detail and is not exported.","sidebar":"tutorialSidebar"},"misc/breaking-changes":{"id":"misc/breaking-changes","title":"Breaking changes","description":"Looking for the full release notes? See the changelog. This page covers only breaking changes and how to migrate.","sidebar":"tutorialSidebar"},"misc/compatibility":{"id":"misc/compatibility","title":"Compatibility","description":"The table below shows which versions of react-native-enriched-markdown","sidebar":"tutorialSidebar"},"misc/contributing":{"id":"misc/contributing","title":"Contributing","description":"react-native-enriched-markdown is an open source library being developed at","sidebar":"tutorialSidebar"},"misc/known-limitations":{"id":"misc/known-limitations","title":"Known limitations","description":"This section covers the rough edges worth knowing about before you hit them.","sidebar":"tutorialSidebar"},"misc/roadmap":{"id":"misc/roadmap","title":"Roadmap","description":"Where the library stands today and what is being worked on next. For what","sidebar":"tutorialSidebar"},"react-native/api-reference/element-structure":{"id":"react-native/api-reference/element-structure","title":"Element structure","description":"This page is the catalog of every Markdown element react-native-enriched-markdown renders","sidebar":"tutorialSidebar"},"react-native/api-reference/enriched-markdown-text":{"id":"react-native/api-reference/enriched-markdown-text","title":"EnrichedMarkdownText","description":"EnrichedMarkdownText renders Markdown content as fully native text - no WebView required. It parses Markdown with md4c and paints it with the platform\'s native text stack (TextKit on iOS, TextView on Android), so selection, accessibility, and font scaling all behave like first-class native text.","sidebar":"tutorialSidebar"},"react-native/api-reference/enriched-markdown-text-input":{"id":"react-native/api-reference/enriched-markdown-text-input","title":"EnrichedMarkdownTextInput","description":"EnrichedMarkdownTextInput is a native, WYSIWYG rich text editor whose content is Markdown: the user sees formatted text as they type - bold looks bold, not bold - while the value is stored as Markdown. Seed it with a Markdown string and read the edited content back as Markdown whenever you need it. Markdown is the source of truth on both sides of the edit, so content round-trips cleanly in and out. It renders with the platform\'s native text stack (UITextView on iOS, EditText on Android), and is an uncontrolled input - it does not hold its value in React state or props, but talks directly to the underlying native component, which keeps it fast and simple.","sidebar":"tutorialSidebar"},"react-native/api-reference/style-properties":{"id":"react-native/api-reference/style-properties","title":"Style properties reference","description":"This page provides a comprehensive reference for all style properties available in react-native-enriched-markdown, passed through the markdownStyle prop.","sidebar":"tutorialSidebar"},"react-native/basics/installation":{"id":"react-native/basics/installation","title":"Installation","description":"This section walks you through adding react-native-enriched-markdown to your app - checking the prerequisites, installing the package, and rebuilding the native projects.","sidebar":"tutorialSidebar"},"react-native/basics/your-first-project":{"id":"react-native/basics/your-first-project","title":"Your first markdown view and editor","description":"With the package installed, let\'s put both components on the screen: EnrichedMarkdownText to display rich text and EnrichedMarkdownTextInput to edit it. By the end of this page you\'ll have rendered your first Markdown and built a minimal editor with a working toolbar button.","sidebar":"tutorialSidebar"},"react-native/guides/custom-block-renderers":{"id":"react-native/guides/custom-block-renderers","title":"Custom block renderers","description":"renderers lets you draw four kinds of block with your own React components: standalone images, videos, links on a line of their own, and code blocks. Use it for a lightbox-aware image, a video player you already ship, a card for a PDF, a YouTube URL or a repository, or a diagram drawn from a mermaid fence. Everything else in the document stays native text, with native selection, accessibility and streaming.","sidebar":"tutorialSidebar"},"react-native/guides/image-caching":{"id":"react-native/guides/image-caching","title":"Image caching","description":"Images in Markdown content are loaded, cached, and reused automatically - no configuration required. This page describes the native image pipeline on iOS, macOS and Android. On web the renderer emits a plain `, so the library adds no caching of its own there and imageRequestHeaders` is not supported.","sidebar":"tutorialSidebar"},"react-native/guides/link-menus":{"id":"react-native/guides/link-menus","title":"Link menus","description":"A long press on a link can do three things in EnrichedMarkdownText, and which one happens depends on what you set and where the text runs:","sidebar":"tutorialSidebar"},"react-native/guides/link-pills":{"id":"react-native/guides/link-pills","title":"Link pills","description":"EnrichedMarkdownText can present a link as a pill: a rounded box with an optional icon and a label, drawn by the native text stack and wrapped as one unit. A file link becomes a chip with a file icon and a short name, a mention becomes an avatar with the user\'s name, and the Markdown underneath stays an ordinary link.","sidebar":"tutorialSidebar"},"react-native/guides/macos":{"id":"react-native/guides/macos","title":"macOS support","description":"react-native-enriched-markdown supports macOS via react-native-macos. The native layer shares code with iOS through a platform abstraction, with macOS-specific implementations for context menus, text selection, and clipboard handling.","sidebar":"tutorialSidebar"},"react-native/guides/markdown-flavors":{"id":"react-native/guides/markdown-flavors","title":"Markdown flavors","description":"EnrichedMarkdownText parses more than the CommonMark core introduced in Core concepts: tables, task lists, LaTeX math, and extra inline syntax. Some of that is gated behind a Markdown flavor, some is toggled through md4cFlags, and a few pieces are always on. This guide explains the flavor first, because it is the main switch, and then the rest of the parsing model.","sidebar":"tutorialSidebar"},"react-native/guides/native-assets":{"id":"react-native/guides/native-assets","title":"Native assets","description":"Two kinds of native assets matter when you ship Enriched Markdown: the fonts","sidebar":"tutorialSidebar"},"react-native/guides/testing":{"id":"react-native/guides/testing","title":"Testing with Jest","description":"EnrichedMarkdownTextInput and EnrichedMarkdownText are Fabric/codegen native components. Under Jest there is no native view manager, so they render as opaque host views with no text children, and every imperative ref method - focus(), setValue(), toggleBold() - is a silent no-op. Nothing throws, which is exactly the problem: you cannot query the rendered Markdown, drive onChangeText, or assert that a toolbar button reached the editor, and the test passes anyway. To make those screens testable, the package ships an importable mock that renders plain React Native primitives and exposes every imperative method as a jest.fn() spy.","sidebar":"tutorialSidebar"},"react-native/guides/web-editor":{"id":"react-native/guides/web-editor","title":"Web editor","description":"EnrichedMarkdownTextInput runs on web as a contentEditable editor built from","sidebar":"tutorialSidebar"},"react-native/guides/web-support":{"id":"react-native/guides/web-support","title":"Web support","description":"EnrichedMarkdownText runs on web as plain React and DOM primitives - the","sidebar":"tutorialSidebar"},"rich-text-formatting/code-highlighting":{"id":"rich-text-formatting/code-highlighting","title":"Code-block syntax highlighting","description":"Fenced code blocks are syntax-highlighted natively via tree-sitter. Highlighting is foreground-only - it recolors tokens and never changes text metrics, so a code block\'s measured height always matches its drawn height. In the React Native package it is on by default on iOS and Android with a curated set of languages, and can be trimmed or disabled to reduce binary size. The standalone iOS SDK ships it as an optional product you enable per view, and the standalone Android SDK as an optional artifact you enable with a plugin - see iOS and Android SDKs.","sidebar":"tutorialSidebar"},"rich-text-formatting/editor-style-text":{"id":"rich-text-formatting/editor-style-text","title":"Editor-style text","description":"The display component normalizes whitespace the way CommonMark does: single newlines collapse into spaces, and runs of blank lines collapse into a single paragraph break. That is the right default for prose, but it means the rendered output does not match the raw line layout the user typed.","sidebar":"tutorialSidebar"},"rich-text-formatting/latex-math":{"id":"rich-text-formatting/latex-math","title":"LaTeX math","description":"EnrichedMarkdownText renders LaTeX math natively, both inline and as block equations:","sidebar":"tutorialSidebar"},"rich-text-formatting/markdown-streaming":{"id":"rich-text-formatting/markdown-streaming","title":"Markdown streaming","description":"When Markdown arrives incrementally - token by token from an LLM, for example - you can render it as it streams instead of waiting for the whole string. The display component fades in newly appended text and handles half-formed block elements gracefully while the rest is still arriving.","sidebar":"tutorialSidebar"},"rich-text-formatting/mentions":{"id":"rich-text-formatting/mentions","title":"Mentions","description":"A mention is just a Markdown link with a custom URL scheme - @Alice. There is no dedicated mention token, which means mentions work with both components: EnrichedMarkdownText displays them as styled, tappable links, and EnrichedMarkdownTextInput additionally lets users author them interactively as they type.","sidebar":"tutorialSidebar"},"user-experience/accessibility":{"id":"user-experience/accessibility","title":"Accessibility","description":"The library ships native accessibility support so screen readers (VoiceOver on iOS and TalkBack on Android) can navigate and announce Markdown content, with semantic labeling, custom navigation controls, and proper announcements for every supported element.","sidebar":"tutorialSidebar"},"user-experience/copy-options":{"id":"user-experience/copy-options","title":"Copy options","description":"When text is selected, the library provides enhanced copy functionality through the native context menu on iOS, macOS and Android.","sidebar":"tutorialSidebar"},"user-experience/rtl":{"id":"user-experience/rtl","title":"RTL support","description":"EnrichedMarkdownText resolves writing direction per paragraph on iOS, Android and web: each paragraph picks its own base direction from its first strong directional character. Arabic, Hebrew, and Persian content right-aligns automatically, even inside an LTR app and even when mixed with English paragraphs in the same document.","sidebar":"tutorialSidebar"}}}}')}}]);